const body = ($input.first().json.body) || {};
const entries = body.entry || [];
const out = [];

for (const entry of entries) {
  for (const change of (entry.changes || [])) {
    const value = change.value || {};
    const phoneNumberId = value.metadata && value.metadata.phone_number_id;
    const messages = value.messages || [];
    // Sem phone_number_id ou sem mensagens = evento de status (entregue/lido) — ignorado por ora.
    if (!phoneNumberId || messages.length === 0) continue;

    const contact = (value.contacts || [])[0];

    for (const message of messages) {
      out.push({
        json: {
          phoneNumberId,
          from: message.from,
          nomeContato: (contact && contact.profile && contact.profile.name) || null,
          messageId: message.id,
          timestamp: message.timestamp || String(Math.floor(Date.now() / 1000)),
          tipo: message.type || 'text',
          texto: (message.text && message.text.body) || null,
        }
      });
    }
  }
}

return out;

const unwrap = (v) => {
  if (v == null) return null;
  if ('stringValue' in v) return v.stringValue;
  if ('integerValue' in v) return parseInt(v.integerValue, 10);
  if ('doubleValue' in v) return v.doubleValue;
  if ('booleanValue' in v) return v.booleanValue;
  if ('timestampValue' in v) return v.timestampValue;
  if ('arrayValue' in v) return (v.arrayValue.values || []).map(unwrap);
  if ('mapValue' in v) {
    const out = {};
    for (const [k, val] of Object.entries(v.mapValue.fields || {})) out[k] = unwrap(val);
    return out;
  }
  return null;
};

const rows = $input.item.json;
const hit = Array.isArray(rows) ? rows.find((r) => r && r.document) : null;
const msg = $('Extrair mensagens Meta').item.json;

if (!hit) {
  return {
    json: {
      empresaEncontrada: false,
      phoneNumberId: msg.phoneNumberId,
      from: msg.from,
      nomeContato: msg.nomeContato,
      texto: msg.texto,
      tipo: msg.tipo,
      timestamp: msg.timestamp,
    }
  };
}

const doc = hit.document;
const f = doc.fields || {};
const get = (k, def) => (f[k] !== undefined ? unwrap(f[k]) : def);
const empresaId = doc.name.split('/').pop();

return {
  json: {
    empresaEncontrada: true,
    empresaId,
    phoneNumberId: msg.phoneNumberId,
    from: msg.from,
    nomeContato: msg.nomeContato,
    texto: msg.texto,
    tipo: msg.tipo,
    timestamp: msg.timestamp,
    nome: get('nome', 'nossa empresa'),
    endereco: get('endereco', ''),
    horario: get('horario', ''),
    descricao: get('descricao', ''),
    iaAtiva: get('iaAtiva', true),
    iaPersonalidade: get('iaPersonalidade', 'simpática, objetiva e profissional'),
    iaSaudacao: get('iaSaudacao', ''),
    iaRegrasAdicionais: get('iaRegrasAdicionais', ''),
    palavrasChaveTransferencia: get('iaPalavrasChaveTransferencia', ['atendente', 'humano', 'pessoa de verdade', 'falar com alguém', 'falar com alguem']),
    whatsappAccessToken: get('whatsappAccessToken', ''),
    telefoneNotificacao: get('whatsappTelefoneNotificacao', ''),
  }
};

const empresa = $('Parse empresa').item.json;

return {
  json: {
    empresaId: empresa.empresaId,
    phoneNumberId: empresa.phoneNumberId,
    from: empresa.from,
    nomeContato: empresa.nomeContato,
    whatsappAccessToken: empresa.whatsappAccessToken,
    telefoneNotificacao: empresa.telefoneNotificacao,
    respostaFinal: 'Só um instante, já vou te transferir para um atendente 🙂',
    transferirHumano: true,
    motivoTransferencia: 'palavra-chave',
  }
};

const unwrap = (v) => {
  if (v == null) return null;
  if ('stringValue' in v) return v.stringValue;
  if ('integerValue' in v) return parseInt(v.integerValue, 10);
  if ('doubleValue' in v) return v.doubleValue;
  if ('booleanValue' in v) return v.booleanValue;
  return null;
};

const docs = $input.item.json.documents || [];
const servicos = docs.map((d) => {
  const f = d.fields || {};
  const get = (k, def) => (f[k] !== undefined ? unwrap(f[k]) : def);
  return {
    nome: get('nome', ''),
    descricao: get('descricao', ''),
    preco: get('preco', null),
    duracaoMinutos: get('duracaoMinutos', null),
    disponivel: get('disponivel', true),
  };
}).filter((s) => s.disponivel);

const servicosTexto = servicos.length
  ? servicos.map((s) => `- ${s.nome}: R$ ${s.preco ?? '(sob consulta)'} ${s.duracaoMinutos ? '· ' + s.duracaoMinutos + ' min' : ''} ${s.descricao ? '— ' + s.descricao : ''}`).join('\n')
  : 'Nenhum serviço cadastrado ainda.';

return { json: { servicosTexto, servicos } };

const empresa = $('Parse empresa').item.json;
const servicosTexto = $json.servicosTexto;

const prompt = `IDENTIDADE
Você é a assistente virtual da empresa ${empresa.nome}.

OBJETIVO
Atender clientes pelo WhatsApp de maneira natural, educada e objetiva.

INFORMAÇÕES DA EMPRESA
Nome: ${empresa.nome}
Endereço: ${empresa.endereco || 'não informado'}
Horário: ${empresa.horario || 'não informado'}
${empresa.iaSaudacao ? 'Saudação preferida: ' + empresa.iaSaudacao : ''}
Personalidade: ${empresa.iaPersonalidade}

SERVIÇOS
${servicosTexto}

REGRAS
- Nunca invente informações.
- Nunca invente preços ou serviços que não estejam listados acima.
- Nunca confirme um agendamento sozinha — colete a preferência do cliente e diga que a confirmação vem em seguida.
- Caso não saiba uma informação, diga que vai verificar e ofereça transferir para um atendente.
- Seja objetiva, use linguagem natural e emojis com moderação.
- Não diga que é humana.
${empresa.iaRegrasAdicionais ? '- ' + empresa.iaRegrasAdicionais : ''}

TRANSFERÊNCIA
Se você não conseguir ajudar, se o cliente insistir em falar com uma pessoa, ou se a situação fugir do que você sabe responder, termine sua resposta com a marcação exata "[[TRANSFERIR_HUMANO]]" em uma linha separada — o sistema cuida do resto.`;

return {
  json: {
    prompt,
    empresaId: empresa.empresaId,
    phoneNumberId: empresa.phoneNumberId,
    from: empresa.from,
    nomeContato: empresa.nomeContato,
    texto: empresa.texto,
    whatsappAccessToken: empresa.whatsappAccessToken,
    telefoneNotificacao: empresa.telefoneNotificacao,
  }
};

const resp = $input.item.json;
let texto = (resp.content && resp.content[0] && resp.content[0].text) || 'Desculpa, tive um problema para responder agora. Já vou te transferir para um atendente.';

const marcador = '[[TRANSFERIR_HUMANO]]';
const transferirHumano = texto.includes(marcador);
if (transferirHumano) {
  texto = texto.replace(marcador, '').trim();
  if (!texto) texto = 'Vou te transferir para um atendente que pode ajudar melhor 🙂';
}

const ctx = $('Montar prompt IA').item.json;

return {
  json: {
    empresaId: ctx.empresaId,
    phoneNumberId: ctx.phoneNumberId,
    from: ctx.from,
    nomeContato: ctx.nomeContato,
    whatsappAccessToken: ctx.whatsappAccessToken,
    telefoneNotificacao: ctx.telefoneNotificacao,
    respostaFinal: texto,
    transferirHumano,
    motivoTransferencia: transferirHumano ? 'ia' : null,
  }
};
